        headers = ['NAME', 'AGE'];
        if (showNamespace) headers.unshift('NAMESPACE');
        rows = resources.map((r) => {
          const meta = r.metadata || {};
          const row = [meta.name || 'resource', '2m'];
          if (showNamespace) row.unshift(meta.namespace || 'default');
          return row;
        });
