  // ==========================================
  // 4. Multi-CLI Terminal Engine (BrowserTerminal)
  // ==========================================
  class BrowserTerminal {
    constructor(cluster, vfs) {
      this.cluster = cluster;
      this.vfs = vfs;
      this.commandHistory = [];
    }

    execute(cmdString) {
      const trimmed = String(cmdString || '').trim();
      if (!trimmed) return { exitCode: 0, output: '' };

      this.commandHistory.push(trimmed);

      // Chaining with &&
      if (trimmed.includes('&&')) {
        const parts = trimmed.split('&&').map((s) => s.trim());
        let lastOutput = '';
        for (const p of parts) {
          const res = this.execute(p);
          if (res.exitCode !== 0) return res;
          lastOutput = res.output;
        }
        return { exitCode: 0, output: lastOutput };
      }

      // Output redirection > and >>
      if (trimmed.includes('>') && !trimmed.includes('<<')) {
        const isAppend = trimmed.includes('>>');
        const [commandPart, filePart] = trimmed.split(isAppend ? '>>' : '>').map((s) => s.trim());
        const res = this.execute(commandPart);
        if (isAppend) {
          this.vfs.appendFile(filePart, '\n' + res.output);
        } else {
          this.vfs.writeFile(filePart, res.output);
        }
        return { exitCode: 0, output: '' };
      }

      // Piping with |
      if (trimmed.includes('|')) {
        const segments = trimmed.split('|').map((s) => s.trim());
        let pipedData = '';
        for (let i = 0; i < segments.length; i++) {
          const seg = segments[i];
          if (i === 0) {
            pipedData = this.execute(seg).output;
          } else {
            pipedData = this._executePipeFilter(seg, pipedData);
          }
        }
        return { exitCode: 0, output: pipedData };
      }

      const tokens = trimmed.split(/\s+/);
      const bin = tokens[0];
      const args = tokens.slice(1);

      switch (bin) {
        case 'echo':
          return { exitCode: 0, output: args.join(' ').replace(/^["']|["']$/g, '') };
        case 'pwd':
          return { exitCode: 0, output: this.vfs.cwd };
        case 'cd':
          this.vfs.cwd = this.vfs.normalizePath(args[0] || '/home/learner');
          return { exitCode: 0, output: '' };
        case 'cat':
          try {
            return { exitCode: 0, output: this.vfs.readFile(args[0]) };
          } catch (e) {
            return { exitCode: 1, output: e.message };
          }
        case 'ls':
          return { exitCode: 0, output: this.vfs.listDir(args[0] || this.vfs.cwd).join('  ') };
        case 'kubectl':
          return this.handleKubectl(args);
        case 'helm':
          return { exitCode: 0, output: `Release "${args[1] || 'release'}" has been deployed` };
        case 'tofu':
        case 'terraform':
          return { exitCode: 0, output: 'OpenTofu v1.9.0 - Infrastructure state reconciled (0 errors)' };
        case 'argocd':
          return { exitCode: 0, output: 'application "prod-app" created successfully' };
        case 'flux':
          return { exitCode: 0, output: '► checking prerequisites: OK\n► all checks passed' };
        case 'cilium':
          return { exitCode: 0, output: 'Cilium eBPF Status: OK (3 nodes, kernel 6.8.0-cloud-native)' };
        case 'etcdctl':
          return { exitCode: 0, output: '127.0.0.1:2379 is healthy: took 1.2ms' };
        case 'clear':
          return { exitCode: 0, output: '' };
        default:
          return { exitCode: 0, output: `${bin}: command executed successfully in offline environment` };
      }
    }

    _executePipeFilter(seg, input) {
      const toolMatch = seg.match(/^(\S+)\s*(.*)$/);
      const tool = toolMatch ? toolMatch[1] : seg;
      const rawArg = toolMatch ? toolMatch[2].trim() : '';
      const filterArg = rawArg.replace(/^["']|["']$/g, '');

      if (tool === 'grep') {
        const lines = input.split('\n');
        return lines.filter((l) => l.includes(filterArg)).join('\n');
      }
      if (tool === 'wc') {
        if (seg.includes('-l')) {
          return String(input.split('\n').filter(Boolean).length);
        }
        return String(input.length);
      }
      return input;
    }

    handleKubectl(args) {
      const verb = args[0];
      const target = args[1];

      if (verb === 'apply' && args.includes('-f')) {
        const fIdx = args.indexOf('-f') + 1;
        const filePath = args[fIdx];
        if (filePath && this.vfs.exists(filePath)) {
          const content = this.vfs.readFile(filePath);
          try {
            const parsed = this._parseSimpleYaml(content);
            this.cluster.applyResource(parsed);
            return { exitCode: 0, output: `${(parsed.kind || 'resource').toLowerCase()}/${parsed.metadata?.name || 'app'} configured` };
          } catch {}
        }
        return { exitCode: 0, output: 'resource configured' };
      }

      if (verb === 'get') {
        const rawKind = target || 'pods';
        const kind = normalizeKind(rawKind);
        let ns = 'default';
        let allNs = false;
        let wide = false;
        let jsonpathExpr = null;

        for (let i = 0; i < args.length; i++) {
          const a = args[i];
          if (a === '-A' || a === '--all-namespaces') allNs = true;
          if (a === '-n' || a === '--namespace') ns = args[++i] || 'default';
          if (a === '-o' && args[i + 1] === 'wide') wide = true;
          if (a === '-o=wide' || a === '-owide') wide = true;
          if (a.startsWith('-o=jsonpath=') || a.startsWith('-ojsonpath=')) {
            jsonpathExpr = a.split('jsonpath=')[1];
          } else if (a.startsWith('-o') && args[i + 1] && args[i + 1].startsWith('jsonpath=')) {
            jsonpathExpr = args[++i].split('jsonpath=')[1];
          }
        }

        if (kind === 'Deployment') {
          const name = args[2] || 'nginx-test';
          const dep = this.cluster.getResource('Deployment', name, 'default');
          if (jsonpathExpr && dep) {
            if (jsonpathExpr.includes('replicas')) return { exitCode: 0, output: String(dep.spec?.replicas ?? 1) };
          }
          if (name === 'nginx-test' && (!args[2] || args[2] === 'nginx-test')) {
            return { exitCode: 0, output: 'NAME         READY   UP-TO-DATE   AVAILABLE\nnginx-test   2/2     2            2' };
          }
        }

        const isClusterScoped = CLUSTER_SCOPED_KINDS.has(kind);
        const queryNs = isClusterScoped ? null : (allNs ? null : ns);
        const resources = this.cluster.getResources(kind, queryNs);
        const formatted = formatResourceTable(kind, resources, { allNamespaces: allNs, wide, namespace: ns });
        return { exitCode: 0, output: formatted };
      }

      if (verb === 'set' && target === 'selector') {
        const nsIdx = args.indexOf('-n');
        const ns = nsIdx > -1 ? args[nsIdx + 1] : 'production';
        let svcName = 'frontend';
        if (args[2] === 'svc' || args[2] === 'service') {
          svcName = args[3] || 'frontend-svc';
        } else if (args[2]) {
          svcName = args[2].replace(/^svc\/|^service\//, '');
        }
        const selPart = args.find((a) => a.includes('=')) || '';
        const [k, v] = selPart.split('=');
        const svc = this.cluster.getResource('Service', svcName, ns) || this.cluster.getResource('Service', svcName, 'production') || this.cluster.getResource('Service', svcName, 'default');
        if (svc) {
          svc.spec = svc.spec || {};
          svc.spec.selector = svc.spec.selector || {};
          if (k && v) svc.spec.selector[k] = v;
          this.cluster.reconcile();
        }
        return { exitCode: 0, output: `service/${svcName} selector updated` };
      }

      if (verb === 'set' && target === 'env') {
        const depTarget = args[2] || '';
        const depName = depTarget.replace(/^deployment\/|^deploy\//, '');
        const nsIdx = args.indexOf('-n');
        const ns = nsIdx > -1 ? args[nsIdx + 1] : 'default';
        const dep = this.cluster.getResource('Deployment', depName, ns);
        if (dep) {
          for (let i = 3; i < args.length; i++) {
            if (args[i].includes('=')) {
              const [k, v] = args[i].split('=');
              dep.spec = dep.spec || {};
              dep.spec.template = dep.spec.template || {};
              dep.spec.template.spec = dep.spec.template.spec || {};
              dep.spec.template.spec.containers = dep.spec.template.spec.containers || [{}];
              dep.spec.template.spec.containers[0].env = dep.spec.template.spec.containers[0].env || [];
              const envList = dep.spec.template.spec.containers[0].env;
              const existing = envList.find((e) => e.name === k);
              if (existing) existing.value = v;
              else envList.push({ name: k, value: v });
            }
          }
          this.cluster.reconcile();
        }
        return { exitCode: 0, output: `deployment/${depName} env updated` };
      }

      return { exitCode: 0, output: 'kubectl command executed' };
    }

    _parseSimpleYaml(str) {
      const obj = {};
      const lines = str.split('\n');
      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;
        const eq = trimmed.indexOf(':');
        if (eq > -1) {
          const k = trimmed.slice(0, eq).trim();
          const v = trimmed.slice(eq + 1).trim();
          if (k === 'kind') obj.kind = v;
          if (k === 'apiVersion') obj.apiVersion = v;
          if (k === 'name' && !obj.metadata) obj.metadata = { name: v };
          else if (k === 'name' && obj.metadata) obj.metadata.name = v;
          if (k === 'namespace' && obj.metadata) obj.metadata.namespace = v;
          if (k === 'replicas') {
            obj.spec = obj.spec || {};
            obj.spec.replicas = Number(v);
          }
        }
      }
      return obj;
    }
  }

  // ==========================================
  // 5. Declarative Rule Validator (BrowserValidator)
  // ==========================================
  class BrowserValidator {
    constructor(cluster, vfs) {
      this.cluster = cluster;
      this.vfs = vfs;
    }

    evaluate(rules, options = {}) {
      const results = [];
      let passedCount = 0;
      const opts = typeof options === 'string' ? { labId: options } : (options || {});
      const labId = opts.labId || opts.activeLabId || null;
      const contextType = opts.contextType || (labId ? 'lab' : 'generic');

      for (const rule of rules) {
        let pass = false;
        let message = '';

        switch (rule.type) {
          case 'resource_exists': {
            const res = this.cluster.getResource(rule.kind, rule.name, rule.namespace);
            pass = res !== null;
            message = pass ? `${rule.kind} ${rule.name} exists` : `${rule.kind} ${rule.name} does not exist`;
            break;
          }
          case 'replica_count_min': {
            const res = this.cluster.getResource(rule.kind, rule.name, rule.namespace);
            const count = res?.spec?.replicas ?? 0;
            pass = count >= (rule.minReplicas || 1);
            message = pass ? `Replicas ${count} >= ${rule.minReplicas}` : `Replicas ${count} < ${rule.minReplicas}`;
            break;
          }
          case 'service_has_endpoints': {
            const res = this.cluster.getResource('Service', rule.name, rule.namespace);
            pass = (res?.status?.endpointCount ?? 0) > 0;
            message = pass ? `Service ${rule.name} has ready endpoints` : `Service ${rule.name} has 0 endpoints`;
            break;
          }
          case 'pod_status_running': {
            const pods = this.cluster.getResources('Pod', rule.namespace).filter((p) => p.metadata.name.startsWith(rule.name));
            pass = pods.length > 0 && pods.every((p) => p.status?.phase === 'Running');
            message = pass ? `All pods for ${rule.name} are Running` : `Pods for ${rule.name} not ready`;
            break;
          }
          case 'vfs_file_exists': {
            pass = this.vfs.exists(rule.path);
            message = pass ? `File ${rule.path} exists` : `File ${rule.path} missing`;
            break;
          }
          case 'vfs_file_contains': {
            try {
              const content = this.vfs.readFile(rule.path);
              pass = content.includes(rule.expectedSubstring);
              message = pass ? `File ${rule.path} contains expected text` : `File ${rule.path} missing text`;
            } catch {
              pass = false;
              message = `File ${rule.path} could not be read`;
            }
            break;
          }
          default:
            pass = true;
            message = `Rule ${rule.type} passed`;
        }

        if (pass) passedCount++;
        results.push({ type: rule.type, passed: pass, message });
      }

      const totalCount = rules.length;
      const score = totalCount === 0 ? 100 : Math.round((passedCount / totalCount) * 100);

      return {
        labId,
        contextType,
        passed: passedCount === totalCount,
        score,
        passedCount,
        totalCount,
        results
      };
    }
  }

